insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('dade2ae0-a083-45a0-873c-2f4dd8c2d705', '1a588546-9176-4d2c-9cab-994c6bf80de9', $$inleiding: drie onderzoeksvragen van het NBS; handelspartners groeiden 1% per jaar$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-context1.png$$,
   $$De Ministers van Economische Zaken en Financiën willen van het Nationaal Bureau voor de Statistiek (NBS) weten hoe de macro- economische ontwikkeling van het land is geweest. Daarom hebben onderzoekers van het NBS een drietal onderzoeksvragen geformuleerd:
1 Heeft de economie van het land in de periode 2000-2019 beter of slechter gepresteerd dan de trendmatige groei van de voornaamste handelspartners? Het nationaal inkomen van de handelspartners groeide gemiddeld met 1% per jaar.
2 Wat is de invloed van de overheid op de conjunctuur geweest?
3 Hoe kan de structurele groei worden bevorderd?$$, 'inline'),
  ('e6722201-0711-4b60-b8df-d530f00bb473', '1a588546-9176-4d2c-9cab-994c6bf80de9', $$kringloopmodel voor 2000 en 2019 met bestedingsevenwicht$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-context2.png$$,
   $$De onderzoekers hebben een macro-economisch kringloopmodel ontwikkeld (zie figuur 1) voor de jaren 2000 en 2019. In beide onderzochte jaren was er sprake van bestedingsevenwicht.$$, 'inline'),
  ('7bbd2806-67ec-4b1a-a184-2a348ed4f254', '1a588546-9176-4d2c-9cab-994c6bf80de9', $$figuur 1: kringloopmodel in 2000 (en 2019) in miljarden euro’s, met verklaring symbolen$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-context3.png$$,
   $$Figuur 1 Kringloopmodel in 2000 (en 2019 tussen haakjes) in miljarden euro’s
Sectoren: gezinnen, overheid, financiële instellingen, bedrijven en buitenland.
C = 199 (260) van gezinnen naar bedrijven
B = 124 (160) van gezinnen naar overheid
O = 106 (135) van overheid naar bedrijven
S van gezinnen naar financiële instellingen
van overheid naar financiële instellingen: ...
I = 28 (46) van financiële instellingen naar bedrijven
E = 197 (211) van buitenland naar bedrijven
M = 180 (202) van bedrijven naar buitenland
Y van bedrijven naar gezinnen
B = belastingen
C = particuliere consumptie
E = export van goederen en diensten
I = bedrijfsinvesteringen
M = import van goederen en diensten
O = overheidsbestedingen
S = particuliere besparingen
Y = nationaal inkomen
(vervangingsinvesteringen en afschrijvingen blijven buiten beschouwing)$$, 'inline'),
  ('738283e3-c328-4c60-a628-1791c6a30594', '1a588546-9176-4d2c-9cab-994c6bf80de9', $$positief nationaal spaarsaldo; bewering over begrotingsbeleid en handelsoverschot$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-context4.png$$,
   $$Het nationaal spaarsaldo is al jaren (sterk) positief. Vanuit het buitenland ontstaat er kritiek op het structureel positieve nationaal spaarsaldo. De onderzoekers beweren daarom: “Het nationaal spaarsaldo en het overheidssaldo in 2019 tonen aan dat de overheid begrotingsbeleid kan voeren om het handelsoverschot te beperken. Dit heeft vervolgens gevolgen voor de conjunctuur van het eigen land en de buurlanden.”$$, 'inline'),
  ('252d5fbe-87f3-4626-b5b1-1c882d58cb34', '1a588546-9176-4d2c-9cab-994c6bf80de9', $$conclusie: R&D-investeringen bevorderen structurele groei$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-context5.png$$,
   $$De onderzoekers concluderen: “Bij eenzelfde inzet van productiefactoren kan door extra investeringen in R&D de structurele groei van de economie worden bevorderd.”$$, 'inline'),
  ('982a6694-1749-4934-b8bf-6fb3ebbe288f', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', $$inleiding: leenstelsel voor studenten met aflossingsperiode van 35 jaar$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-context1.png$$,
   $$In een land kunnen studenten zelf hun vervolgopleiding in het hoger onderwijs financieren door middel van een lening bij de overheid. Na het afronden van de opleiding moet deze worden terugbetaald. De overheid heeft een voorwaarde toegevoegd aan het leenstelsel om jongeren aan te zetten tot studeren, ondanks de risico’s van lenen. De voorwaarde is dat de aflossingsperiode van de opgebouwde studieschuld 35 jaar wordt (langer dan de standaard periode voor aflossingen van langlopende schulden).$$, 'inline'),
  ('d87ea83b-0958-473c-ac5f-c1df188e7dd0', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', $$vóór het leenstelsel: hogere rente bij commerciële banken voor lage inkomens$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-context2.png$$,
   $$Voordat het leenstelsel werd ingevoerd, waren vooral studenten uit huishoudens met een laag inkomen voor de financiering van hun studie aangewezen op commerciële banken. Vanwege een risico op wanbetaling rekenden deze banken een hogere rente voor dit type leningen. Hierdoor werd de vermogensverdeling tussen huishoudens beïnvloed.$$, 'inline'),
  ('9cde415b-f3e7-4ca9-a1fe-404877690e62', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', $$collegegeld van € 12.000 en een subsidie aan de aanbieder$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-context3.png$$,
   $$Onderwijsinstellingen in het hoger onderwijs (aanbieders) rekenen € 12.000 per jaar collegegeld. Het hoger onderwijs wordt toegankelijker als het collegegeld daalt door bijvoorbeeld een subsidie aan de aanbieder. Het Plan Bureau (PB) onderzoekt de effecten van een subsidie op het collegegeld voor de markt van hoger onderwijs (zie figuur 1).$$, 'inline'),
  ('e12cdd86-3f23-4d7b-84e8-c073713f6b30', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', $$figuur 1: vraag- en aanbodmodel van hoger onderwijs$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-context4.png$$,
   $$Figuur 1 Vraag- en aanbodmodel van hoger onderwijs
verticale as: P (x €1.000); horizontale as: Q (aantal studenten x 10.000)
Dalende vraaglijn Qv; stijgende aanbodlijnen Qa₀ en Qa₁ (Qa₁ rechts van Qa₀, pijl naar rechts); Qv en Qa₀ snijden bij P = 12.$$, 'inline'),
  ('fa0c62c1-ffe7-423f-bfaa-0bfd598c1d20', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', $$de subsidie heeft gevolgen voor de doelmatigheid$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-context5.png$$,
   $$De subsidie heeft gevolgen voor de doelmatigheid van het hoger onderwijs.$$, 'inline'),
  ('62c0a0f2-4bba-44a5-a116-714ad8da921e', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', $$stelling PB: positief extern effect verhoogt de brede welvaart$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-context6.png$$,
   $$Het PB stelt: “Bij het hoger onderwijs treedt door de subsidie een positief extern effect op waardoor de maatschappelijke (brede) welvaart stijgt.”$$, 'inline'),
  ('3f9e29cd-f04b-434f-9984-500d15500b8b', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', $$uitwerkbijlage vraag 9: figuur A en figuur B$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-context7.png$$,
   $$uitwerkbijlage vraag 9
Figuur A en Figuur B: beide een kopie van figuur 1 (vraaglijn Qv, aanbodlijnen Qa₀ en Qa₁, P = 12 bij het snijpunt van Qv en Qa₀); verticale as P (x €1.000), horizontale as Q (aantal studenten x 10.000)$$, 'uitwerkbijlage'),
  ('6e17fec2-2e8a-4f40-979e-b2076dc8f149', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$inleiding: PostNV heeft een tijdelijk wettelijk monopolie op brievenpost$$,
   $$economie-vwo-2023-ii-kostenpost-context1.png$$,
   $$De overheid van een land vindt het belangrijk dat brievenpost dagelijks wordt bezorgd tegen een voor iedereen betaalbare prijs en heeft PostNV een tijdelijk wettelijk monopolie gegeven. PostNV streeft naar maximale totale winst. De winstgevendheid van brievenpost komt onder druk te staan, omdat gezinnen en bedrijven brievenpost steeds vaker vervangen door e-mail en andere digitale communicatievormen.$$, 'inline'),
  ('107a0922-b75a-484f-b75e-4388d4396f6f', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$BEO onderzoekt de markt van brievenpost met een model$$,
   $$economie-vwo-2023-ii-kostenpost-context2.png$$,
   $$Bureau Economisch Onderzoek (BEO) onderzoekt de markt van brievenpost en de effecten van de afgenomen vraag naar brievenpost. Daartoe hanteert het BEO onderstaand model.$$, 'inline'),
  ('dc8ce110-dbbd-4f36-813d-4421a3963ecc', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$model: vraagfuncties Qv₀ en Qv₁ en totale kosten$$,
   $$economie-vwo-2023-ii-kostenpost-context3.png$$,
   $$Qv₀ = − 500P + 1.225
Qv₁ = − 500P + 1.125
TK = 0,66Q + 300
waarbij:
Qv₀ = aantal bezorgde brieven in miljoenen in de uitgangssituatie
Qv₁ = aantal bezorgde brieven in miljoenen bij afgenomen behoefte
TK = totale kosten in miljoenen euro’s
P = prijs per brief in euro’s$$, 'inline'),
  ('7853556b-4be4-44fb-a8b1-9f2df790b6f6', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$uitgangssituatie: 447,5 miljoen brieven bij een prijs van € 1,56$$,
   $$economie-vwo-2023-ii-kostenpost-context4.png$$,
   $$In de uitgangssituatie worden er 447,5 miljoen brieven bezorgd. BEO rekent in het model met een prijs van € 1,56 (afgerond).$$, 'inline'),
  ('81d32858-e559-4161-8e99-5bca34e9a2e4', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$aandeelhouders willen winst per product van minstens 10% van de GTK$$,
   $$economie-vwo-2023-ii-kostenpost-context5.png$$,
   $$PostNV streeft naar maximale winst, maar aandeelhouders willen daarbij dat de winst per product minstens 10% van de gemiddelde totale kosten is.$$, 'inline'),
  ('37e8b1d2-d87e-4be7-9fb5-d950bbb6c5ed', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$reactie Van Gorkum: geknikte prijselasticiteit$$,
   $$economie-vwo-2023-ii-kostenpost-context6.png$$,
   $$Econoom Van Gorkum reageert: “Uit marktonderzoek blijkt dat in de nieuwe situatie, consumenten en bedrijven prijselastisch reageren bij een verhoging van het posttarief en prijsinelastisch bij een verlaging van het tarief.”$$, 'inline'),
  ('203be41c-5d0b-44c3-bf70-814c938c8d5b', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$figuur 1: indexcijfers afzet en omzet brievenpostmarkt (2010 = 100)$$,
   $$economie-vwo-2023-ii-kostenpost-context7.png$$,
   $$Figuur 1 Indexcijfers afzet en omzet van PostNV op de brievenpostmarkt (2010 = 100)
Lijngrafiek 2011-2015, verticale as 0 tot 120. Legenda: omzet (doorgetrokken lijn), afzet (stippellijn).
Omzet en afzet dalen beide over 2011-2015; de afzet daalt sterker dan de omzet (exacte waarden: zie de figuur).$$, 'inline'),
  ('d622883d-ecb5-4fa5-9e62-39b75e759771', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$figuur 2: indexcijfers afzet en omzet pakketbezorgingsmarkt (2012 = 100)$$,
   $$economie-vwo-2023-ii-kostenpost-context8.png$$,
   $$Figuur 2 Indexcijfers afzet en omzet van PostNV op de pakketbezorgingsmarkt (2012 = 100)
Lijngrafiek 2012-2016, verticale as 0 tot 160. Legenda: omzet (doorgetrokken lijn), afzet (stippellijn).
Beide beginnen op 100 in 2012 en stijgen tot 2016; de afzet stijgt sterker dan de omzet (exacte waarden: zie de figuur).$$, 'inline'),
  ('42917782-575a-4994-8ce2-dd4430a3dc1e', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$mogelijke kruissubsidie van brievenpost naar pakketbezorging$$,
   $$economie-vwo-2023-ii-kostenpost-context9.png$$,
   $$Naast brievenpost is PostNV ook actief in pakketbezorging waar PostNV een grote speler is. Het is daarom mogelijk dat PostNV aan kruissubsidie heeft gedaan om de concurrentiepositie op de markt van pakketbezorging te versterken. Kruissubsidie betekent dat PostNV brievenpost relatief duurder maakt om pakketpost relatief goedkoper te maken om zo beter te kunnen concurreren op de markt van pakketpost.$$, 'inline'),
  ('f24fb226-df48-4adc-ba84-2347f113f344', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', $$principaal-agentprobleem tussen overheid en PostNV; mededingingsautoriteit als toezichthouder$$,
   $$economie-vwo-2023-ii-kostenpost-context10.png$$,
   $$Tussen de overheid en PostNV is er sprake van een principaal-agent probleem. De mededingingsautoriteit is daarom door de overheid aangesteld als toezichthouder.$$, 'inline'),
  ('6e44c57f-acea-4853-917a-4b41b691bbe6', '6b32ca63-f188-4d52-82a0-3ade1f61c3f6', $$inleiding: Japanse centrale bank met duaal mandaat verlaagt de rente$$,
   $$economie-vwo-2023-ii-doelbewust-deprecieren-context1.png$$,
   $$De Japanse Centrale Bank (JCB) heeft een duaal mandaat. Dit heeft geleid tot ruim monetair beleid: het rentepercentage waarvoor Japanse banken geld lenen bij de JCB is op 1 januari 2020 verlaagd van 0,35% naar 0,1%.$$, 'inline'),
  ('af32d26f-ee85-4c23-885f-17f4dd07dc71', '6b32ca63-f188-4d52-82a0-3ade1f61c3f6', $$yen deprecieert 20% tot 0,00793 dollar$$,
   $$economie-vwo-2023-ii-doelbewust-deprecieren-context2.png$$,
   $$Het beleid leidde tot een scherpe daling van de waarde van de yen ten opzichte van andere valuta. De Japanse yen is met 20% gedeprecieerd ten opzichte van de dollar tot een waarde van 0,00793 Amerikaanse dollar.$$, 'inline'),
  ('e6671c6a-ec4b-4b83-9ffd-b6c68e514840', '6b32ca63-f188-4d52-82a0-3ade1f61c3f6', $$stelling FED-woordvoerder over het reële inkomen van Amerikaanse huishoudens$$,
   $$economie-vwo-2023-ii-doelbewust-deprecieren-context3.png$$,
   $$De depreciatie van de yen heeft gevolgen voor de koopkracht van Amerikaanse huishoudens. Een woordvoerder van de FED stelt dat de hogere waarde van de dollar ten opzichte van de yen op termijn een positief effect heeft op het reële inkomen van het gemiddelde Amerikaanse huishouden.$$, 'inline'),
  ('eadcde2f-1ec2-4a21-8637-16f0bd71a04d', '6b32ca63-f188-4d52-82a0-3ade1f61c3f6', $$model: monetair beleid van JCB en FED beïnvloedt de exportopbrengsten$$,
   $$economie-vwo-2023-ii-doelbewust-deprecieren-context4.png$$,
   $$Figuur 1 toont een model. Hierin heeft het monetair beleid van de JCB en de FED via de valutamarkt een sterke invloed op de onderlinge exportopbrengsten.$$, 'inline'),
  ('5fdae1bf-91e8-4657-b1ce-990815f7933a', '6b32ca63-f188-4d52-82a0-3ade1f61c3f6', $$figuur 1: spelboom exportopbrengsten Japan en VS, met toelichting$$,
   $$economie-vwo-2023-ii-doelbewust-deprecieren-context5.png$$,
   $$Figuur 1 Exportopbrengsten Japan en VS
Spelboom: eerst kiest de JCB (ongewijzigd beleid of ruim beleid), daarna de FED (ongewijzigd beleid of ruim beleid). Uitbetalingen (Japan; VS):
JCB ongewijzigd, FED ongewijzigd: 100; 100
JCB ongewijzigd, FED ruim: 75; 104
JCB ruim, FED ongewijzigd: 112; 62,5
JCB ruim, FED ruim: 100; 100
− De getallen betreffen uitsluitend de onderlinge exportopbrengst van Japan en de VS in de eigen valuta, uitgedrukt in afgeronde gehele indexcijfers (de huidige situatie is gelijk aan “ongewijzigd beleid; ongewijzigd beleid”).
− De exportprijs wordt uitsluitend bepaald door de hoogte van de wisselkoers. Andere factoren die invloed hebben op de exportprijs worden constant verondersteld.$$, 'inline'),
  ('6b5d1403-f131-4554-a86c-d109dd05ab33', '6b32ca63-f188-4d52-82a0-3ade1f61c3f6', $$conclusies i en ii over het Nash-evenwicht$$,
   $$economie-vwo-2023-ii-doelbewust-deprecieren-context6.png$$,
   $$Uit het model kunnen de volgende conclusies worden getrokken: i. Het model heeft een Nash-evenwicht. ii. Dit Nash-evenwicht zal gevolgen hebben voor het binnenlands prijspeil van zowel de VS als Japan (die beide in een hoogconjunctuur verkeren) waardoor de internationale concurrentiepositie kan verslechteren.$$, 'inline'),
  ('d752a23d-13d3-46ab-b7c3-d721c8317422', '794eab71-1a46-4147-9007-192fbba21166', $$inleiding: daling consumenten- en producentenvertrouwen$$,
   $$economie-vwo-2023-ii-vertrouwen-context1.png$$,
   $$De afgelopen maanden is in een land onder invloed van maatschappelijke onrust het consumenten- en producentenvertrouwen sterk gedaald, waardoor de consumptie en de investeringen zijn gedaald.$$, 'inline'),
  ('22af6a76-9e30-4da7-9a3e-42292c4dfc9f', '794eab71-1a46-4147-9007-192fbba21166', $$analyse met het Keynesiaans kruis en het IS-MB-GA-model; Y₀ is potentiële productie$$,
   $$economie-vwo-2023-ii-vertrouwen-context2.png$$,
   $$Econoom Ana Valderrama onderzoekt de macro-economische ontwikkelingen met behulp van het Keynesiaans kruis en het IS-MB-GA model. Figuur 1 toont de uitgangssituatie voor de daling van het vertrouwen waarbij Y₀ gelijk is aan de potentiële productie. De daling van de bestedingen is alleen nog in het Keynesiaans kruis weergegeven.$$, 'inline'),
  ('16b43a23-d5f9-42db-be4d-1d1d451751ef', '794eab71-1a46-4147-9007-192fbba21166', $$figuur 1: Keynesiaans kruis en IS-MB-GA-model$$,
   $$economie-vwo-2023-ii-vertrouwen-context3.png$$,
   $$Figuur 1 Keynesiaans kruis en IS-MB-GA model
bovenste diagram: verticale as EV, horizontale as inkomen (Y); 45°-lijn en de bestedingslijnen EV₀ en EV₁ (EV₁ lager); snijpunten bij Y₁ en Y₀
middelste diagram: verticale as rente (r), horizontale as inkomen (Y); horizontale MB₀ bij r₀ en dalende IS₀, die elkaar snijden bij Y₀
onderste diagram: verticale as inflatie (π), horizontale as inkomen (Y); stijgende GA₀ door π₀ bij Y₀$$, 'inline'),
  ('14531899-e787-4d56-9fad-e153f6debf31', '794eab71-1a46-4147-9007-192fbba21166', $$inkomen daalt sterker dan de autonome bestedingen$$,
   $$economie-vwo-2023-ii-vertrouwen-context4.png$$,
   $$Het Keynesiaans kruis toont aan dat het inkomen sterker daalt dan de autonome bestedingen.$$, 'inline'),
  ('a7bb58ac-2ff4-4975-9fe6-374e70fb982f', '794eab71-1a46-4147-9007-192fbba21166', $$negatieve output gap; GA-curve toont dalende productie$$,
   $$economie-vwo-2023-ii-vertrouwen-context5.png$$,
   $$Vanuit het Keynesiaans kruis blijkt dat in het IS-MB-GA diagram een negatieve output gap ontstaat. De GA-curve toont daarbij aan dat de productie daalt.$$, 'inline'),
  ('d67351c2-0d83-4e97-b052-2e4911fa26d8', '794eab71-1a46-4147-9007-192fbba21166', $$aanname: centrale bank brengt de output gap in één stap naar nul$$,
   $$economie-vwo-2023-ii-vertrouwen-context6.png$$,
   $$Econoom Valderrama stelt: “Ik neem aan dat de centrale bank de beleidsrente aanpast aan de verwachte inflatie en dat ze effectief de rente met één stap aanpassen zodanig dat deze de economie op een output gap van nul brengt.”$$, 'inline'),
  ('8d0933f0-f65a-4cb2-879b-5ffcd3b684f2', '794eab71-1a46-4147-9007-192fbba21166', $$aanpassingsmechanisme hangt af van de economische visie$$,
   $$economie-vwo-2023-ii-vertrouwen-context7.png$$,
   $$Valderrama stelt dat het aanpassingsmechanisme van de economie wordt bepaald door de economische visie van de centrale bank.$$, 'inline'),
  ('804d810d-88f3-42ae-902b-9e3a81035515', '794eab71-1a46-4147-9007-192fbba21166', $$pleidooi voor cao’s met een kortere looptijd$$,
   $$economie-vwo-2023-ii-vertrouwen-context8.png$$,
   $$Econoom Valderrama stelt: “De mate van onzekerheid en de trage transitie van de economie vloeien voort uit cao’s met een lange looptijd. Ik pleit daarom voor cao’s met een kortere looptijd, waardoor de GA-curve steiler wordt en de economie sneller naar het nieuwe evenwicht gaat.”$$, 'inline'),
  ('44c07197-8e21-4368-b5aa-324f8046b993', '794eab71-1a46-4147-9007-192fbba21166', $$uitwerkbijlage vraag 23: figuur C$$,
   $$economie-vwo-2023-ii-vertrouwen-context9.png$$,
   $$uitwerkbijlage vraag 23
Figuur C: kopie van figuur 1 (Keynesiaans kruis met EV₀, EV₁, Y₁ en Y₀; IS₀ en MB₀ bij r₀; GA₀ door π₀ bij Y₀)$$, 'uitwerkbijlage'),
  ('fa296150-ccb2-4d89-a3d7-41a94cbeab86', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$inleiding: krapte op de markt voor sociale huurwoningen met maximumhuur van € 850$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context1.png$$,
   $$In de gemeente Reder is er sprake van een enorme krapte op de woningmarkt, bijvoorbeeld bij de deelmarkt sociale huurwoningen. Sociale huurwoningen zijn woningen die aangeboden worden aan de lagere inkomensgroepen. Daarbij geldt een maximumhuur (door de gemeente ingesteld) van € 850 per maand. Woningbouwvereniging VastWonen is de enige aanbieder van sociale huurwoningen in de gemeente Reder. VastWonen is genoodzaakt om met wachtlijsten te werken voor deze huurwoningen. Econoom Mark Knopper onderzoekt de woningmarkt in Reder en neemt aan dat sociale huurwoningen homogene goederen zijn.$$, 'inline'),
  ('d9a6ab39-8d13-4a41-9038-384ff313dc33', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$tabel 1: huidige financiële gegevens VastWonen$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context2.png$$,
   $$Tabel 1 Huidige financiële gegevens VastWonen
maximumhuur | € 850 per woning per maand
woningvoorraad | 6.800 woningen
totale kosten (per maand) in euro’s | TK = 450Q + 1.400.000
gemiddelde huuropbrengst per woning per maand in euro’s | GO = −0,125Q + 2.150
Q | aantal sociale huurwoningen$$, 'inline'),
  ('bbdab073-310c-49b8-89dd-f8cb2f739682', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$stelling: zonder maximumhuur verdwijnt de wachtlijst bij omzetmaximalisatie$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context3.png$$,
   $$VastWonen stelt dat bij afschaffing van de maximumhuur, de wachtlijst verdwijnt als VastWonen maximale omzet als doelstelling hanteert.$$, 'inline'),
  ('e19d469e-6f49-4850-8308-e6be1749dab6', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$plan: kantoorpanden ombouwen, gefinancierd met hypothecaire leningen$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context4.png$$,
   $$De gemeente houdt vast aan de maximumhuur. Om de krapte aan te pakken wil de directeur van VastWonen oude kantoorpanden opkopen van de gemeente en deze ombouwen tot sociale huurwoningen. De aankoop- en verbouwingsplannen moeten worden gefinancierd door middel van hypothecaire leningen (lening met onderpand).$$, 'inline'),
  ('529bf219-4d5c-479d-869c-232474fcc5a0', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$onderbouwing Knopper: lage rente en laag risico$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context5.png$$,
   $$Econoom Knopper vindt het een goed plan en onderbouwt het als volgt: “De huidige lage hypotheekrente in combinatie met de huidige situatie op de sociale huurwoningmarkt zorgen voor een laag risico voor VastWonen, waardoor de schulden voor de woningbouwvereniging geen financieel probleem vormen.”$$, 'inline'),
  ('e1abc22a-7c58-4ee8-a7dc-74c37b179d8f', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$particuliere huurwoningen in de vrije sector worden krapper$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context6.png$$,
   $$In de gemeente Reder zijn er naast sociale huurwoningen ook particuliere huurwoningen. Een particuliere huurwoning is een woning in de vrije sector (zonder overheidsregulering) en de huur wordt bepaald door vraag en aanbod. Ook deze markt wordt krapper (zie tabel 2).$$, 'inline'),
  ('2726b153-2023-4733-97fb-cb200dd668ca', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$tabel 2: gegevens particuliere huurwoningen in Reder$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context7.png$$,
   $$Tabel 2 Gegevens particuliere huurwoningen in Reder
| Ontwikkeling ten opzichte van jaar eerder
aantal vrijgekomen huurwoningen | −9,9%
gemiddelde huur | +6%
hoogte van de middeninkomens | +3%$$, 'inline'),
  ('0e915de6-3b0f-4c52-adf4-7dcf1303892b', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$inkomenselasticiteit van +0,4 voor middeninkomens$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context8.png$$,
   $$Uit onderzoek blijkt dat de inkomenselasticiteit van particuliere huurwoningen van de middeninkomens gelijk is aan +0,4.$$, 'inline'),
  ('9f9a7155-505f-4f3e-b061-74c27d815b62', '98252e7c-91a2-4925-8f99-b2d0937e6d19', $$verklaring makelaar: vraag- en aanbodkant zorgen voor stijgende huren$$,
   $$economie-vwo-2023-ii-de-woningmarkt-in-de-knel-context9.png$$,
   $$Een makelaar verklaart de grote prijsstijging van particuliere huurwoningen: “Ontwikkelingen aan zowel de vraagkant als de aanbodkant van de particuliere huurwoningmarkt zorgen voor stijgende huren.”$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('b6c920e8-9587-40c5-a0ad-269d7e7ea91c', '1a588546-9176-4d2c-9cab-994c6bf80de9', 1,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}]'::jsonb,
   '["kringloopmodel", "nationaal inkomen berekenen", "bestedingsevenwicht", "Y = C + I + O + E − M", "bestedingsmethode"]'::jsonb,
   $$Met een kringloopmodel het nationaal inkomen berekenen via de bestedingen.$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-vraag1.png$$, $$1p 1 Laat met een berekening zien dat het nationaal inkomen € 350 miljard bedraagt in 2000.$$, array['dade2ae0-a083-45a0-873c-2f4dd8c2d705', 'e6722201-0711-4b60-b8df-d530f00bb473', '7bbd2806-67ec-4b1a-a184-2a348ed4f254']::uuid[]),
  ('8e930011-55f2-4339-968e-b7ab24a0d7e4', '1a588546-9176-4d2c-9cab-994c6bf80de9', 2,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}, {"domain": "Welvaart en groei", "subdomain": "Structurele groei"}]'::jsonb,
   '["economische groei berekenen", "gemiddelde jaarlijkse groei", "trendmatige groei", "nationaal inkomen", "groeivoet"]'::jsonb,
   $$Met een berekening van de gemiddelde jaarlijkse groei de prestatie vergelijken met de trendgroei van handelspartners.$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-vraag2.png$$, $$2p 2 Heeft het land in 2000-2019 beter of slechter dan het beschreven trendmatige gemiddelde van de voornaamste handelspartners gepresteerd? Motiveer je keuze met een berekening.$$, array['dade2ae0-a083-45a0-873c-2f4dd8c2d705', '7bbd2806-67ec-4b1a-a184-2a348ed4f254']::uuid[]),
  ('9594f059-c0c5-47f4-b4a1-0fac83f7e4b7', '1a588546-9176-4d2c-9cab-994c6bf80de9', 3,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Begrotingsbeleid"}]'::jsonb,
   '["overheidssaldo", "kringloopmodel", "overheidsbestedingen", "belastingen", "bestedingen"]'::jsonb,
   $$Met het kringloopmodel bepalen of de overheid per saldo bijdraagt aan de totale bestedingen.$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-vraag3.png$$, $$2p 3 Leg aan de hand van het kringloopmodel uit of de overheid in 2019 een positieve of negatieve bijdrage heeft geleverd aan het totaal van de bestedingen.$$, array['7bbd2806-67ec-4b1a-a184-2a348ed4f254']::uuid[]),
  ('eedb07ea-e697-4d87-8457-bbc23dd2ef14', '1a588546-9176-4d2c-9cab-994c6bf80de9', 4,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Begrotingsbeleid"}]'::jsonb,
   '["nationaal spaarsaldo", "overheidssaldo", "handelsoverschot", "S = I + (O − B) + (E − M)", "expansief begrotingsbeleid"]'::jsonb,
   $$Uitleggen hoe begrotingsbeleid via het overheidssaldo het handelsoverschot en de conjunctuur van buurlanden beïnvloedt.$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-vraag4.png$$, $$2p 4 Leg de bewering van de onderzoekers uit.$$, array['7bbd2806-67ec-4b1a-a184-2a348ed4f254', '738283e3-c328-4c60-a628-1791c6a30594']::uuid[]),
  ('a99d4ed7-180a-4bb3-b785-f12e30037b86', '1a588546-9176-4d2c-9cab-994c6bf80de9', 5,
   '[{"domain": "Welvaart en groei", "subdomain": "Structurele groei"}]'::jsonb,
   '["totale factorproductiviteit", "R&D", "productiefunctie", "structurele groei", "innovatie"]'::jsonb,
   $$Uitleggen hoe R&D via de totale factorproductiviteit de structurele groei bevordert.$$,
   $$economie-vwo-2023-ii-macro-economische-ontwikkelingen-vraag5.png$$, $$2p 5 Leg de conclusie van de onderzoekers uit. Betrek de totale factorproductiviteit in je antwoord.$$, array['252d5fbe-87f3-4626-b5b1-1c882d58cb34']::uuid[]),
  ('3f597199-2d25-4df8-a5af-6820a18af4df', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', 6,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}]'::jsonb,
   '["studielening", "aflossingsperiode", "leenrisico", "lenen", "terugbetalingscapaciteit"]'::jsonb,
   $$Verklaren hoe een langere aflossingsperiode het risico van lenen voor een student verkleint.$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-vraag6.png$$, $$1p 6 Verklaar hoe de voorwaarde het leenrisico van een student vermindert.$$, array['982a6694-1749-4934-b8bf-6fb3ebbe288f']::uuid[]),
  ('d6de649c-718c-4fcc-8f05-d0fdb025e41f', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', 7,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}, {"domain": "Welvaart en groei", "subdomain": "Structurele groei"}]'::jsonb,
   '["leenstelsel", "investeren in menselijk kapitaal", "toekomstig inkomen", "consumptieve bestedingen", "ruilen over de tijd"]'::jsonb,
   $$Uitleggen hoe lenen voor onderwijs via een hoger toekomstig inkomen de consumptie op termijn verhoogt.$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-vraag7.png$$, $$2p 7 Leg uit dat het leenstelsel op termijn een positief effect heeft op de consumptieve bestedingen.$$, array['982a6694-1749-4934-b8bf-6fb3ebbe288f']::uuid[]),
  ('f56b6dad-d6c9-4adb-8215-7a36bb61a9d1', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', 8,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}, {"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}]'::jsonb,
   '["vermogensverdeling", "rente", "risico op wanbetaling", "risico-opslag", "vermogensongelijkheid"]'::jsonb,
   $$Uitleggen hoe een hogere rente voor leners met een laag inkomen de vermogensverdeling schever maakt.$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-vraag8.png$$, $$2p 8 Leg uit op welke wijze de vermogensverdeling tussen huishoudens werd beïnvloed in de periode voordat het leenstelsel werd ingevoerd.$$, array['d87ea83b-0958-473c-ac5f-c1df188e7dd0']::uuid[]),
  ('45384c9a-e02f-4baa-a889-2a91fea92f73', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', 9,
   '[{"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}]'::jsonb,
   '["subsidie per eenheid", "subsidiebedrag", "welvaartsverlies", "Harberger-driehoek", "totaal surplus", "doelmatigheid"]'::jsonb,
   $$In een vraag-en-aanbodgrafiek het subsidiebedrag en het welvaartsverlies van een subsidie aangeven.$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-vraag9.png$$, $$2p 9 Analyseer de gevolgen van de subsidie voor de doelmatigheid. Ga als volgt te werk:
− Arceer in de uitwerkbijlage (figuur A) het subsidiebedrag van de overheid.
− Arceer in de uitwerkbijlage (figuur B) het verloren surplus dat ontstaat door de overheidssubsidie.$$, array['9cde415b-f3e7-4ca9-a1fe-404877690e62', 'e12cdd86-3f23-4d7b-84e8-c073713f6b30', 'fa0c62c1-ffe7-423f-bfaa-0bfd598c1d20', '3f9e29cd-f04b-434f-9984-500d15500b8b']::uuid[]),
  ('3603cc78-d7fd-474e-979b-b9c369e803b9', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', 10,
   '[{"domain": "Samenwerken en onderhandelen", "subdomain": "Suboptimale situaties"}, {"domain": "Welvaart en groei", "subdomain": "Inkomen, welvaart en welzijn"}]'::jsonb,
   '["positief extern effect", "brede welvaart", "onderwijs", "maatschappelijke baten", "subsidie"]'::jsonb,
   $$Uitleggen hoe een positief extern effect van onderwijs de maatschappelijke welvaart verhoogt.$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-vraag10.png$$, $$2p 10 Leg de stelling van het PB uit.$$, array['62c0a0f2-4bba-44a5-a116-714ad8da921e']::uuid[]),
  ('efbee833-459b-44c9-a613-2e515a8060b1', 'bdd4936a-e37d-4704-8e5c-c6a362adab03', 11,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Begrotingsbeleid"}]'::jsonb,
   '["inverdieneffect", "subsidie", "belastingopbrengsten", "hoger inkomen", "overheidsfinanciën"]'::jsonb,
   $$Uitleggen welke inverdieneffecten een subsidie op onderwijs voor de overheid oplevert.$$,
   $$economie-vwo-2023-ii-markt-voor-hoger-onderwijs-vraag11.png$$, $$2p 11 Leg uit dat er inverdieneffecten optreden door de subsidie op het collegegeld.$$, array['9cde415b-f3e7-4ca9-a1fe-404877690e62']::uuid[]),
  ('788650d9-80a7-40bc-813d-7389f62b551b', 'a6e4d1c8-2972-4c5e-8b95-543dfb82d840', 12,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
